import test from 'node:test';import assert from 'node:assert/strict';
import {showcaseShouldPaint} from '../character-showcase.js';
test('hidden and disconnected showcases never perform a canvas redraw',()=>{assert.equal(showcaseShouldPaint({hidden:true,dirty:true}),false);assert.equal(showcaseShouldPaint({connected:false,dirty:true}),false);});
test('reduced-motion portraits redraw only for actual changes',()=>{assert.equal(showcaseShouldPaint({reduced:true,now:1000}),false);assert.equal(showcaseShouldPaint({reduced:true,dirty:true}),true);});
test('automatic rotation is capped at thirty paints per second and pauses during manual turns',()=>{assert.equal(showcaseShouldPaint({now:1010,lastPaint:1000}),false);assert.equal(showcaseShouldPaint({now:1040,lastPaint:1000}),true);assert.equal(showcaseShouldPaint({now:1040,lastPaint:1000,dragging:true}),false);assert.equal(showcaseShouldPaint({now:1040,lastPaint:1000,manualUntil:8000}),false);assert.equal(showcaseShouldPaint({now:1040,lastPaint:1000,manualUntil:8000,dirty:true}),true);});
test('a GPU shader failure keeps character selection usable through the canvas fallback',async()=>{
 const {characterShowcase}=await import('../character-showcase.js');const names=['document','Image','requestAnimationFrame','cancelAnimationFrame','addEventListener','removeEventListener'],saved=Object.fromEntries(names.map(n=>[n,globalThis[n]]));let replacement,deleted=0,raf;
 const gl={VERTEX_SHADER:1,FRAGMENT_SHADER:2,COMPILE_STATUS:3,createProgram:()=>({}),createShader:()=>({}),shaderSource(){},compileShader(){},getShaderParameter:()=>false,deleteShader(){deleted++;},deleteProgram(){deleted++;},getExtension:()=>null};
 class Canvas extends EventTarget{constructor(gpu=false){super();this.gpu=gpu;this.style={};this.className='traveller-model';this.isConnected=true;this.attrs={};}getContext(kind){return kind==='webgl'?(this.gpu?gl:null):{};}setAttribute(k,v){this.attrs[k]=v;}getAttribute(k){return this.attrs[k];}replaceWith(c){replacement=c;this.isConnected=false;}after(){} }
 const doc=new EventTarget();doc.hidden=false;doc.createElement=()=>new Canvas();const resize=new EventTarget();Object.assign(globalThis,{document:doc,Image:class{},requestAnimationFrame:fn=>{raf=fn;return 1;},cancelAnimationFrame(){},addEventListener:resize.addEventListener.bind(resize),removeEventListener:resize.removeEventListener.bind(resize)});
 try{const controller=characterShowcase(new Canvas(true),{reduced:true});assert.ok(replacement,'fallback canvas replaces failed GPU canvas');assert.ok(deleted>=2,'partially built GPU resources released');assert.doesNotThrow(()=>controller.select(1));assert.doesNotThrow(()=>controller.turn(.4));assert.doesNotThrow(()=>controller.setLegacy('ceramic-arm'));assert.doesNotThrow(()=>controller.setLegacy('missing'));assert.doesNotThrow(()=>controller.setLegacy('reed-ear'));assert.doesNotThrow(()=>raf(100));controller.destroy();controller.destroy();}finally{for(const name of names){if(saved[name]===undefined)delete globalThis[name];else globalThis[name]=saved[name];}}
});
